<template><div><div class="page-head"><div><h1>Business Insights</h1><p>Turn your transaction data into decisions about growth, cash, profit and risk.</p></div><div class="action-row"><input v-model="from" class="input" type="date"><input v-model="to" class="input" type="date"><button class="btn btn-primary" @click="load">Refresh</button></div></div><div class="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4"><div v-for="m in cards" :key="m.label" class="card metric"><div class="metric-label">{{m.label}}</div><div class="metric-value mt-2">{{m.money?money(m.value):format(m.value)}}</div><div class="metric-trend mt-3">{{m.note}}</div></div></div><div class="mt-4 grid grid-cols-1 gap-4 xl:grid-cols-2"><div class="card p-5"><h2 class="text-sm font-extrabold">Decision signals</h2><div class="mt-4 space-y-3"><div v-for="i in insights" :key="i.title" class="rounded-2xl border border-slate-100 p-4 dark:border-slate-800"><div class="flex items-center gap-2"><span class="status" :class="i.level==='risk'?'status-danger':i.level==='warn'?'status-warning':'status-success'">{{i.level}}</span><b class="text-xs">{{i.title}}</b></div><p class="mt-2 text-[11px] leading-5 text-slate-500 dark:text-slate-400">{{i.message}}</p></div></div></div><div class="card p-5"><div class="flex justify-between"><div><h2 class="text-sm font-extrabold">Daily revenue</h2><p class="mt-1 text-[10px] text-slate-400">Selected period</p></div><span class="status status-neutral">{{period}}</span></div><div class="mt-6 flex h-48 items-end gap-2"><div v-for="d in data.daily_sales||[]" :key="d.day" class="flex-1"><div class="mx-auto max-w-10 rounded-t-lg bg-gradient-to-t from-indigo-700 to-cyan-400" :style="{height:`${bar(d.total)}%`}" :title="money(d.total)"></div><div class="mt-2 text-center text-[9px] text-slate-400">{{day(d.day)}}</div></div></div></div></div><div class="mt-4 grid grid-cols-1 gap-4 lg:grid-cols-2"><div class="card overflow-hidden"><div class="px-5 py-4"><h2 class="text-sm font-extrabold">Top clients</h2></div><table class="data-table"><thead><tr><th>Client</th><th class="text-right">Sales</th></tr></thead><tbody><tr v-for="c in data.top_clients||[]" :key="c.id"><td>{{c.name}}</td><td class="text-right">{{money(c.sales_total)}}</td></tr></tbody></table></div><div class="card overflow-hidden"><div class="px-5 py-4"><h2 class="text-sm font-extrabold">Top products</h2></div><table class="data-table"><thead><tr><th>Product</th><th>Qty</th><th class="text-right">Revenue</th></tr></thead><tbody><tr v-for="p in data.top_products||[]" :key="p.id"><td>{{p.name}}</td><td>{{p.quantity}}</td><td class="text-right">{{money(p.revenue)}}</td></tr></tbody></table></div></div></div></template>
<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {api} from '../../services/api';import {formatDate as formatDisplayDate} from '../../utils/date';const today=new Date(),monthStart=new Date(today.getFullYear(),today.getMonth(),1);const iso=(d:Date)=>d.toISOString().slice(0,10);const from=ref(iso(monthStart)),to=ref(iso(today)),data=ref<any>({cards:{}});function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}function format(v:any){return new Intl.NumberFormat('en-TZ').format(Number(v||0))}const period=computed(()=>`${from.value} → ${to.value}`);const max=computed(()=>Math.max(1,...(data.value.daily_sales||[]).map((x:any)=>Number(x.total||0))));function bar(v:any){return Math.max(8,Number(v||0)/max.value*100)}function day(v:any){return new Intl.DateTimeFormat('en-TZ',{timeZone:'Africa/Dar_es_Salaam',weekday:'short'}).format(new Date(v)).slice(0,3)}const cards=computed(()=>[{label:'Revenue',value:data.value.cards?.revenue,money:true,note:'Completed sales'},{label:'Gross profit',value:data.value.cards?.gross_profit,money:true,note:'Revenue less item cost'},{label:'Net profit',value:data.value.cards?.net_profit,money:true,note:'Gross profit less expenses'},{label:'Receivables',value:data.value.cards?.receivables,money:true,note:`${format(data.value.cards?.open_invoices)} open invoices`}]);const insights=computed(()=>data.value.insights||[]);async function load(){data.value=(await api.get('/reports/overview',{params:{from:from.value,to:to.value}})).data}onMounted(load)</script>
